// Define the DHT22 pin connections
#define DHTPIN 2  // Choose any digital pin

// Define the type of DHT sensor we're using
#define DHTTYPE DHT22

// Define the calibration constants
const float calibrationTemp = 22.5;  // Known temperature (°C)
const float calibrationHumid = 60.0;  // Known humidity (%)

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  // Read the temperature and humidity from the DHT22
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Calculate the calibration coefficients
  float A = (calibrationTemp - temperature) / (calibrationHumid - humidity);
  float B = calibrationTemp - A * calibrationHumid;

  // Print the calibration coefficients
  Serial.print("A = ");
  Serial.print(A);
  Serial.println(", B = ");
  Serial.print(B);
  Serial.println();

  delay(1000);  // Wait 1 second before reading again
}
